package kr.tong.sky;

import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Bitmap;import android.net.Uri;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;

/** Debug-only, network-disabled AF browser -> capture -> SQLite -> saved UI probe. */
public final class LabInstrumentation extends Instrumentation {
 static final String SEARCH="https://wwws.airfrance.co.kr/search/flights/0",AUTH="https://wwws.airfrance.co.kr/auth/login",CAL="SharedSearchLowestFareOffersForSearchQuery",DETAIL="SearchResultAvailableOffersQuery";
 final JSONArray cases=new JSONArray();final ConcurrentHashMap<String,Activity> resumed=new ConcurrentHashMap<>();final ConcurrentHashMap<String,AtomicInteger> requests=new ConcurrentHashMap<>();Context ctx;volatile String phase="created";int launchCounter;String date=LocalDate.now(Search.KST).plusDays(12).toString(),detailDate=LocalDate.now(Search.KST).plusDays(13).toString();Set<String> initialDatabases;
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){ctx=getTargetContext();Bundle result=new Bundle();try{
  checkpoint("probe.start");check(BuildConfig.DEBUG,"debug probe required");check(ctx.checkSelfPermission(android.Manifest.permission.INTERNET)==PackageManager.PERMISSION_DENIED,"probe must not have INTERNET permission");initialDatabases=new HashSet<>(Arrays.asList(ctx.databaseList()));
  runFetchCalendar();runXhrDetail();runRejectedResponses();runAuthBoundary();runPersistenceAndBack();
  JSONObject report=progress().put("success",true).put("status","passed").put("phase","probe.complete").put("requestCounts",requestSummary()).put("webViewPackage",WebView.getCurrentWebViewPackage()==null?"none":WebView.getCurrentWebViewPackage().packageName);save(report);android.util.Log.i("TongDeviceProbe","OFFLINE_DEVICE_PROBE_PASS "+report);result.putString("stream","OFFLINE_DEVICE_PROBE_PASS "+report+"\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable failure){failure.printStackTrace();android.util.Log.e("TongDeviceProbe","OFFLINE_DEVICE_PROBE_FAIL phase="+phase,failure);try{save(progress().put("success",false).put("status","failed").put("error",failure.toString()));}catch(Exception ignored){}result.putString("stream","OFFLINE_DEVICE_PROBE_FAIL phase="+phase+" "+failure+"\n");finish(Activity.RESULT_CANCELED,result);}}
 JSONObject progress()throws Exception{return new JSONObject().put("appVersion",BuildConfig.VERSION_NAME).put("api",Build.VERSION.SDK_INT).put("networkPermission",false).put("status","running").put("phase",phase).put("cases",cases).put("runtimeMaxHeapBytes",Runtime.getRuntime().maxMemory());}
 JSONObject requestSummary()throws Exception{JSONObject out=new JSONObject();for(var item:requests.entrySet())out.put(item.getKey(),item.getValue().get());return out;}
 void save(JSONObject value)throws Exception{File temp=new File(ctx.getFilesDir(),"device-startup-report.tmp");try(OutputStream out=new FileOutputStream(temp)){out.write(value.toString(2).getBytes(StandardCharsets.UTF_8));}check(temp.renameTo(new File(ctx.getFilesDir(),"device-startup-report.json")),"report atomic commit failed");}
 void checkpoint(String stage)throws Exception{phase=stage;android.util.Log.i("TongDeviceProbe","DEVICE_STAGE "+stage+" cases="+cases.length());save(progress());}
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 interface Condition{boolean get()throws Exception;}
 void await(String message,long timeout,Condition condition)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<end){if(condition.get())return;Thread.sleep(80);}throw new AssertionError(message+" phase="+phase);}
 void onMain(Runnable task){if(Looper.myLooper()==Looper.getMainLooper()){task.run();return;}CountDownLatch latch=new CountDownLatch(1);Throwable[] error={null};new Handler(Looper.getMainLooper()).post(()->{try{task.run();}catch(Throwable failure){error[0]=failure;}finally{latch.countDown();}});try{check(latch.await(10,TimeUnit.SECONDS),"main callback timeout");}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new AssertionError(interrupted);}if(error[0]!=null)throw new AssertionError("main callback failed",error[0]);}
 @Override public void callActivityOnResume(Activity activity){super.callActivityOnResume(activity);String id=activity.getIntent().getStringExtra("__af_probe_launch");if(id!=null)resumed.put(id,activity);}
 @Override public void callActivityOnDestroy(Activity activity){super.callActivityOnDestroy(activity);String id=activity.getIntent().getStringExtra("__af_probe_launch");if(id!=null)resumed.remove(id,activity);}
 AirFranceActivity launch()throws Exception{String id="af-probe-"+(++launchCounter);onMain(()->ctx.startActivity(new Intent(ctx,AirFranceActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK).putExtra("__af_probe_launch",id)));await("AF activity did not resume",12000,()->resumed.get(id) instanceof AirFranceActivity);AirFranceActivity a=(AirFranceActivity)resumed.get(id);check(a!=null&&!a.closed&&a.resumed,"AF lifecycle not ready");return a;}
 String eval(WebView view,String script)throws Exception{CountDownLatch latch=new CountDownLatch(1);AtomicReference<String> out=new AtomicReference<>();onMain(()->view.evaluateJavascript(script,value->{out.set(value);latch.countDown();}));check(latch.await(10,TimeUnit.SECONDS),"WebView evaluate callback timed out");return out.get();}
 JSONObject packet(WebView view)throws Exception{String raw=eval(view,"JSON.stringify(window.__tongAF?window.__tongAF.drain():{schema:1,status:'not-installed',records:[]})");Object value=new JSONTokener(raw==null?"null":raw).nextValue();return value instanceof String?new JSONObject((String)value):value instanceof JSONObject?(JSONObject)value:new JSONObject();}
 int responseCount(){int total=0;for(var item:requests.entrySet())if(!"document".equals(item.getKey())&&!"favicon".equals(item.getKey()))total+=item.getValue().get();return total;}
 void count(String kind){requests.computeIfAbsent(kind,k->new AtomicInteger()).incrementAndGet();}
 WebResourceResponse response(String mime,String body){return new WebResourceResponse(mime,"UTF-8",200,"OK",Map.of("Access-Control-Allow-Origin","https://wwws.airfrance.co.kr","Cache-Control","no-store"),new ByteArrayInputStream(body.getBytes(StandardCharsets.UTF_8)));}
 void openFixture(AirFranceActivity a,String url)throws Exception{
  onMain(()->{check(a.browser==null,"fixture requires a fresh AF browser");WebView view=new WebView(a);a.configure(view);a.browser=view;a.browserBox.removeAllViews();a.browserBox.addView(view,new FrameLayout.LayoutParams(-1,-1));WebViewClient delegate=view.getWebViewClient();view.setWebViewClient(new WebViewClient(){
   @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){String path=r.getUrl().getPath(),kind=r.getUrl().getQueryParameter("fixture");try{if(r.isForMainFrame()){count("document");return response("text/html",page());}if("/favicon.ico".equals(path)){count("favicon");return response("image/x-icon","");}if(kind!=null){count(kind);return response("application/json",fixtureResponse(kind));}count("unexpected");return response("text/plain","");}catch(Exception e){throw new AssertionError("fixture generation failed",e);}}
   @Override public void onPageStarted(WebView v,String u,Bitmap icon){delegate.onPageStarted(v,u,icon);}
   @Override public void onPageCommitVisible(WebView v,String u){delegate.onPageCommitVisible(v,u);}
   @Override public void onPageFinished(WebView v,String u){delegate.onPageFinished(v,u);}
   @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return delegate.shouldOverrideUrlLoading(v,r);}
   @Override public boolean shouldOverrideUrlLoading(WebView v,String u){return delegate.shouldOverrideUrlLoading(v,u);}
   @Override public void onReceivedHttpError(WebView v,WebResourceRequest r,WebResourceResponse p){delegate.onReceivedHttpError(v,r,p);}
   @Override public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){delegate.onReceivedError(v,r,e);}
  });a.openOfficial();view.stopLoading();a.captureAllowed=true;view.loadUrl(url);});
  await("fixture document did not finish",12000,()->"true".equals(eval(a.browser,"document.readyState==='complete'&&!!document.getElementById('fetch-calendar')")));
  if(SEARCH.equals(url))await("production capture script not installed",10000,()->"true".equals(eval(a.browser,"!!window.__tongAF")));
 }
 void click(AirFranceActivity a,String button)throws Exception{eval(a.browser,"window.__fixtureDone=false;document.getElementById("+JSONObject.quote(button)+").click();true");await("fixture request did not finish",10000,()->"true".equals(eval(a.browser,"window.__fixtureDone===true")));}
 JSONArray stored(String day)throws Exception{try(AirFranceDb db=new AirFranceDb(ctx)){return db.records("ICN","CDG",YearMonth.from(LocalDate.parse(day)));}}
 long countRows()throws Exception{try(AirFranceDb db=new AirFranceDb(ctx)){long total=0;JSONArray routes=db.routes();Set<YearMonth> months=new HashSet<>(Arrays.asList(YearMonth.from(LocalDate.parse(date)),YearMonth.from(LocalDate.parse(detailDate))));for(int i=0;i<routes.length();i++){JSONObject route=routes.getJSONObject(i);for(YearMonth month:months)total+=db.records(route.getString("origin"),route.getString("destination"),month).length();}return total;}}
 void waitSaved(AirFranceActivity a,long before)throws Exception{await("captured records not saved",10000,()->countRows()>before);await("saved capture was not acknowledged",8000,()->packet(a.browser).optJSONArray("records")!=null&&packet(a.browser).getJSONArray("records").length()==0);check(!a.closed,"AF activity closed during import");}
 void importCaptured(AirFranceActivity a)throws Exception{await("capture queue empty",10000,()->packet(a.browser).optJSONArray("records")!=null&&packet(a.browser).getJSONArray("records").length()>0);JSONObject p=packet(a.browser);String text=p.toString();check(!text.contains("AF-OFFLINE-PRIVATE")&&!text.contains("offline@example.invalid"),"capture retained fixture credential or auth fields");int before=responseCount();onMain(a::importCurrent);Thread.sleep(80);check(responseCount()==before,"import issued an additional provider request");}
 void screenshot(String name)throws Exception{Bitmap bitmap=getUiAutomation().takeScreenshot();check(bitmap!=null,"screenshot unavailable");try(OutputStream out=new FileOutputStream(new File(ctx.getFilesDir(),name))){check(bitmap.compress(Bitmap.CompressFormat.PNG,100,out),"screenshot encoding failed");}finally{bitmap.recycle();}}
 String text(View view){StringBuilder b=new StringBuilder();if(view instanceof TextView t)b.append(t.getText()).append('\n');if(view instanceof ViewGroup g)for(int i=0;i<g.getChildCount();i++)b.append(text(g.getChildAt(i)));return b.toString();}
 void showRows(AirFranceActivity a)throws Exception{showRows(a,date);}
 void showRows(AirFranceActivity a,String selectedDate)throws Exception{onMain(()->{a.month=YearMonth.from(LocalDate.parse(selectedDate));a.showSaved();});await("saved rows not rendered",10000,()->{boolean[] visible={false};onMain(()->visible[0]=a.rows.length()>0&&a.days!=null&&text(a.days).contains("마일"));return visible[0];});}
 void passed(String name,long start)throws Exception{cases.put(new JSONObject().put("name",name).put("passed",true).put("elapsedMs",SystemClock.elapsedRealtime()-start));checkpoint(name+".PASS");}
 void close(AirFranceActivity a)throws Exception{onMain(a::finish);await("AF activity did not close",6000,()->a.closed);check(a.worker.awaitTermination(6,TimeUnit.SECONDS),"AF worker did not release its DB");}
 void assertNoCollectors(){onMain(()->check(CollectionService.active==null&&AsianaCollectionService.activeOz==null,"AF browser must not start KE/OZ collectors"));}
 void runFetchCalendar()throws Exception{
  long start=SystemClock.elapsedRealtime();checkpoint("FETCH_CALENDAR.START");AirFranceActivity a=launch();try{check(a.browser==null,"opening AF tab must not automatically load a provider page");long before=countRows();int requestBefore=responseCount();openFixture(a,SEARCH);check(responseCount()==requestBefore,"capture installation made an unsolicited request");screenshot("af-probe-browser.png");click(a,"fetch-calendar");importCaptured(a);waitSaved(a,before);check(countRows()==before+1,"calendar fixture must create exactly one observation");JSONArray rows=stored(date);boolean found=false;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(date.equals(row.optString("date"))&&"calendar".equals(row.optString("kind"))){check(!row.getBoolean("confirmed")&&row.isNull("remainingSeats"),"calendar price must not fabricate confirmed seats");check(row.getLong("miles")==80000,"calendar reward miles changed");found=true;}}check(found,"real AF SQLite calendar row missing");check(responseCount()==requestBefore+1,"fetch capture or import duplicated a request");showRows(a);onMain(()->{String shown=text(a.days);check(shown.contains("달력 참고")&&shown.contains("해당 운임 좌석 수 알 수 없음"),"saved calendar UI does not distinguish candidate price and unknown fare-seat count");});assertNoCollectors();passed("Fetch official-schema calendar through production capture and SQLite",start);}finally{close(a);}
 }
 void runXhrDetail()throws Exception{
  long start=SystemClock.elapsedRealtime();checkpoint("XHR_DETAIL.START");AirFranceActivity a=launch();try{long before=countRows();int requestBefore=responseCount();openFixture(a,SEARCH);click(a,"xhr-detail");importCaptured(a);waitSaved(a,before);check(countRows()==before+2,"two validated fare quotes must remain distinct");JSONArray rows=stored(detailDate);boolean unknown=false,known=false;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!detailDate.equals(row.optString("date"))||!"offers".equals(row.optString("kind")))continue;check(row.getBoolean("confirmed"),"available offer must remain a detailed observation");check(row.getJSONArray("flights").length()==1&&"AF267".equals(row.getJSONArray("flights").getJSONObject(0).getString("number")),"flight identity not preserved");if(row.isNull("remainingSeats"))unknown=true;else if(row.getInt("remainingSeats")==2)known=true;}
   check(unknown&&known,"absent fare-seat count must stay null while explicit two seats remain two");check(responseCount()==requestBefore+1,"XHR capture or import duplicated a request");showRows(a,detailDate);onMain(()->{String shown=text(a.days);check(shown.contains("상세 조회")&&shown.contains("해당 운임 표시 2석")&&shown.contains("해당 운임 좌석 수 알 수 없음"),"saved offer UI lost fare-seat-count distinctions");});screenshot("af-probe-saved.png");assertNoCollectors();passed("XHR detailed reward quotes preserve known and unknown fare-seat counts",start);}finally{close(a);}
 }
 void runRejectedResponses()throws Exception{
  long start=SystemClock.elapsedRealtime();checkpoint("REJECTED_RESPONSES.START");AirFranceActivity a=launch();try{long before=countRows();int requestBefore=responseCount();openFixture(a,SEARCH);click(a,"fetch-cash");Thread.sleep(100);check(packet(a.browser).getJSONArray("records").length()==0,"cash search was captured as a reward");click(a,"fetch-malformed");await("malformed reward response not classified",8000,()->"unsupported_response".equals(packet(a.browser).optString("status")));click(a,"fetch-auth");Thread.sleep(100);JSONObject p=packet(a.browser);check(p.getJSONArray("records").length()==0,"unsupported/auth response created a seat observation");check(!p.toString().contains("AF-OFFLINE-PRIVATE")&&!p.toString().contains("offline@example.invalid"),"authentication response leaked into capture packet");onMain(a::importCurrent);Thread.sleep(150);check(countRows()==before,"invalid/cash/auth responses changed stored observations");check(responseCount()==requestBefore+3,"rejected responses caused extra requests");passed("Cash malformed and authentication responses leave saved observations intact",start);}finally{close(a);}
 }
 void runAuthBoundary()throws Exception{
  long start=SystemClock.elapsedRealtime();checkpoint("AUTH_BOUNDARY.START");AirFranceActivity a=launch();try{long before=countRows();int requestBefore=responseCount();openFixture(a,AUTH);check("false".equals(eval(a.browser,"!!window.__tongAF")),"capture script installed on an authentication page");click(a,"fetch-calendar");Thread.sleep(100);check("false".equals(eval(a.browser,"!!window.__tongAF")),"reward-shaped traffic on login page installed a capture hook");onMain(a::importCurrent);Thread.sleep(150);check(countRows()==before,"authentication page import changed stored observations");check(responseCount()==requestBefore+1,"login-page handling generated extra requests");onMain(()->check(a.status.getText().toString().contains("검색"),"authentication boundary guidance missing"));passed("Login page remains a standard browser without reward capture",start);}finally{close(a);}
 }
 void runPersistenceAndBack()throws Exception{
  long start=SystemClock.elapsedRealtime();checkpoint("PERSISTENCE.START");long before=countRows();int requestBefore=responseCount();AirFranceActivity first=launch(),current=first;try{showRows(first);String id=first.getIntent().getStringExtra("__af_probe_launch");onMain(first::recreate);await("AF recreation did not resume a new activity",12000,()->resumed.get(id) instanceof AirFranceActivity&&resumed.get(id)!=first);current=(AirFranceActivity)resumed.get(id);check(current.browser==null,"recreation must not silently start a provider request");showRows(current);check(countRows()==before&&before>=3,"AF observations were lost across recreation");AirFranceActivity restored=current;onMain(restored::onBackPressed);check(!restored.isFinishing()&&!restored.showingSaved,"back from saved results must return to AF browser panel");onMain(restored::onBackPressed);await("back did not finish AF activity",6000,restored::isFinishing);check(responseCount()==requestBefore,"saved results or recreation sent a provider request");assertNoCollectors();check(initialDatabases.contains("tong-sky.db")==new File(ctx.getDatabasePath("tong-sky.db").getPath()).exists(),"AF tests created or removed the KE database");check(initialDatabases.contains("tong-sky-asiana.db")==new File(ctx.getDatabasePath("tong-sky-asiana.db").getPath()).exists(),"AF tests created or removed the OZ database");passed("AF SQLite observations survive recreation and saved-view back navigation",start);}finally{if(!current.closed)close(current);}
 }
 JSONObject request(String operation,boolean reward)throws Exception{boolean calendar=operation.equals(CAL);JSONObject req=new JSONObject().put("bookingFlow",reward?"REWARD":"CASH").put("type","DAY").put("passengers",new JSONArray().put(new JSONObject().put("type","ADT"))).put("commercialCabins",new JSONArray().put("BUSINESS")).put("requestedConnections",new JSONArray().put(new JSONObject().put("origin",new JSONObject().put("type","AIRPORT").put("code","ICN")).put("destination",new JSONObject().put("type","AIRPORT").put("code","CDG")).put("departureDate",calendar?date:detailDate).put("dateInterval",date+"/"+detailDate)));JSONObject vars=new JSONObject().put("bookingFlow",reward?"REWARD":"CASH").put(calendar?"lowestFareOffersRequest":"availableOfferRequestBody",req).put(calendar?"activeConnection":"activeConnectionIndex",0);return new JSONObject().put("operationName",operation).put("variables",vars);}
 String page()throws Exception{return "<!doctype html><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{font-family:sans-serif;padding:20px;color:#172d45}input,button{display:block;margin:12px 0;padding:12px;max-width:100%}small{color:#64748b}</style><h2>오프라인 검사 화면</h2><small>실제 항공사 화면·계정이 아닙니다.</small><input id='email' value='offline@example.invalid'><input id='password' type='password' value='AF-OFFLINE-PRIVATE-PASSWORD'><button id='fetch-calendar' onclick=\"send('calendar',false,false)\">달력 검색 검사</button><button id='xhr-detail' onclick=\"send('detail',true,false)\">상세 검색 검사</button><button id='fetch-cash' onclick=\"send('cash',false,true)\">일반 결제 응답 검사</button><button id='fetch-malformed' onclick=\"send('malformed',false,false)\">잘못된 응답 검사</button><button id='fetch-auth' onclick=\"send('auth',false,false)\">인증 응답 제외 검사</button><p id='echo'></p><script>const CAL="+request(CAL,true)+",DETAIL="+request(DETAIL,true)+",CASH="+request(CAL,false)+";function send(kind,xhr,cash){const q=cash?CASH:kind==='detail'?DETAIL:CAL;const url=kind==='auth'?'/auth/token?fixture=auth':'/gql/v1?operationName='+encodeURIComponent(q.operationName)+'&fixture='+kind;function done(){window.__fixtureDone=true;document.getElementById('echo').textContent='검사 응답 수신';}if(xhr){const x=new XMLHttpRequest();x.open('POST',url);x.setRequestHeader('Content-Type','application/json');x.onload=done;x.onerror=done;x.send(JSON.stringify(q));}else fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(q)}).then(r=>r.text()).then(done,done);}</script>";}
 JSONObject product(int miles,Integer seats,String fare)throws Exception{JSONObject connection=new JSONObject().put("cabinClass","BUSINESS").put("priceInMiles",new JSONObject().put("currency","MILES").put("displayType","FARE_MILES").put("totalPrice",miles)).put("fareFamily",new JSONObject().put("code",fare)).put("tax",new JSONObject().put("currencyCode","KRW").put("amount",153000));if(seats!=null)connection.put("numberOfSeatsAvailable",seats);return new JSONObject().put("connections",new JSONArray().put(connection));}
 String fixtureResponse(String kind)throws Exception{
  if("malformed".equals(kind))return "{not-valid-json";
  if("auth".equals(kind))return new JSONObject().put("accessToken","AF-OFFLINE-PRIVATE-TOKEN").put("profile",new JSONObject().put("email","offline@example.invalid")).toString();
  if("detail".equals(kind)){JSONObject segment=new JSONObject().put("origin",new JSONObject().put("code","ICN")).put("destination",new JSONObject().put("code","CDG")).put("departureDateTime",detailDate+"T10:00:00+09:00").put("marketingFlight",new JSONObject().put("carrier",new JSONObject().put("code","AF")).put("number","267"));JSONObject itinerary=new JSONObject().put("activeConnection",new JSONObject().put("segments",new JSONArray().put(segment))).put("flightProducts",new JSONArray().put(product(85000,null,"STANDARD")).put(product(90000,2,"FLEX")));return new JSONObject().put("data",new JSONObject().put("availableOffers",new JSONObject().put("offerItineraries",new JSONArray().put(itinerary)))).put("accessToken","AF-OFFLINE-PRIVATE-TOKEN").toString();}
  JSONObject row=new JSONObject().put("flightDate",date).put("currency","cash".equals(kind)?"KRW":"MILES").put("totalPrice",80000).put("noFlight",false);return new JSONObject().put("data",new JSONObject().put("lowestFareOffers",new JSONObject().put("lowestOffers",new JSONArray().put(row)))).put("accessToken","AF-OFFLINE-PRIVATE-TOKEN").toString();
 }
}
